namespace RecipeSharing.Models;

public enum RecipeCategory
{
    Breakfast,
    Lunch,
    Dinner,
    Desserts,
    Appetizers,
    Beverages
}

public record Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public RecipeCategory Category { get; set; }
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.Collections.Concurrent;
using RecipeSharing.Models;

namespace RecipeSharing.Services;

public class RecipeService
{
    private readonly ConcurrentDictionary<int, Recipe> _recipes = new();
    private int _nextId;

    public RecipeService()
    {
        var seeds = new List<Recipe>
        {
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = RecipeCategory.Breakfast,
                Ingredients = ["2 cups all-purpose flour", "2 tablespoons sugar", "1 tablespoon baking powder", "1/2 teaspoon salt", "2 eggs", "1 1/2 cups milk", "1/4 cup melted butter"],
                Steps = ["Mix flour, sugar, baking powder, and salt in a bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Heat a griddle over medium heat and grease lightly.", "Pour 1/4 cup batter per pancake and cook until bubbles form, then flip.", "Serve warm with maple syrup and fresh berries."],
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Chicken Caesar Wrap", Category = RecipeCategory.Lunch,
                Ingredients = ["2 grilled chicken breasts, sliced", "4 large flour tortillas", "2 cups romaine lettuce, chopped", "1/2 cup Caesar dressing", "1/4 cup grated Parmesan", "1/2 cup croutons, crushed"],
                Steps = ["Slice grilled chicken into thin strips.", "Warm tortillas in a dry skillet for 30 seconds each.", "Spread Caesar dressing down the center of each tortilla.", "Layer lettuce, chicken, Parmesan, and crushed croutons.", "Fold sides in and roll tightly.", "Slice in half and serve."],
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Beef Stir-Fry", Category = RecipeCategory.Dinner,
                Ingredients = ["1 lb flank steak, thinly sliced", "2 tablespoons soy sauce", "1 tablespoon sesame oil", "1 red bell pepper, sliced", "1 cup broccoli florets", "2 cloves garlic, minced", "1 tablespoon cornstarch", "Cooked rice for serving"],
                Steps = ["Toss steak slices with soy sauce and cornstarch.", "Heat sesame oil in a wok over high heat.", "Sear beef in batches until browned, then set aside.", "Stir-fry bell pepper, broccoli, and garlic for 3 minutes.", "Return beef to the wok and toss everything together.", "Serve immediately over steamed rice."],
                AverageRating = 4.7, RatingCount = 15
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = RecipeCategory.Desserts,
                Ingredients = ["4 oz dark chocolate", "1/2 cup unsalted butter", "1 cup powdered sugar", "2 eggs", "2 egg yolks", "6 tablespoons flour", "Butter and cocoa for ramekins"],
                Steps = ["Preheat oven to 425°F. Grease ramekins with butter and dust with cocoa.", "Melt chocolate and butter together in a microwave, stirring every 30 seconds.", "Stir in powdered sugar until smooth.", "Whisk in eggs and egg yolks, then fold in flour.", "Divide batter among ramekins.", "Bake for 12-14 minutes until edges are firm but center is soft. Invert onto plates and serve immediately."],
                AverageRating = 4.9, RatingCount = 20
            },
            new()
            {
                Id = 5, Title = "Bruschetta", Category = RecipeCategory.Appetizers,
                Ingredients = ["1 French baguette, sliced", "4 ripe tomatoes, diced", "1/4 cup fresh basil, chopped", "2 cloves garlic, minced", "2 tablespoons olive oil", "1 tablespoon balsamic vinegar", "Salt and pepper to taste"],
                Steps = ["Preheat oven to 400°F.", "Arrange baguette slices on a baking sheet and toast for 5 minutes.", "Mix tomatoes, basil, garlic, olive oil, and balsamic vinegar.", "Season with salt and pepper.", "Spoon tomato mixture onto toasted bread.", "Serve immediately as a fresh appetizer."],
                AverageRating = 4.3, RatingCount = 10
            },
            new()
            {
                Id = 6, Title = "Mango Smoothie", Category = RecipeCategory.Beverages,
                Ingredients = ["2 ripe mangoes, peeled and cubed", "1 cup Greek yogurt", "1/2 cup orange juice", "1 tablespoon honey", "1 cup ice cubes", "Fresh mint for garnish"],
                Steps = ["Add mango, yogurt, orange juice, and honey to a blender.", "Blend on high until smooth.", "Add ice cubes and blend again until frothy.", "Pour into glasses.", "Garnish with a sprig of fresh mint.", "Serve immediately."],
                AverageRating = 4.6, RatingCount = 9
            }
        };

        foreach (var recipe in seeds)
        {
            _recipes[recipe.Id] = recipe;
        }

        _nextId = seeds.Count;
    }

    public List<Recipe> GetAllRecipes() => [.. _recipes.Values.OrderBy(r => r.Id)];

    public List<Recipe> GetByCategory(RecipeCategory category) =>
        [.. _recipes.Values.Where(r => r.Category == category).OrderBy(r => r.Id)];

    public Recipe? GetById(int id) => _recipes.GetValueOrDefault(id);

    public Recipe AddRecipe(Recipe recipe)
    {
        var id = Interlocked.Increment(ref _nextId);
        recipe.Id = id;
        _recipes[id] = recipe;
        return recipe;
    }

    public void SubmitRating(int recipeId, int rating)
    {
        if (_recipes.TryGetValue(recipeId, out var recipe))
        {
            lock (recipe)
            {
                var totalRating = recipe.AverageRating * recipe.RatingCount + rating;
                recipe.RatingCount++;
                recipe.AverageRating = Math.Round(totalRating / recipe.RatingCount, 1);
            }
        }
    }
}

@page "/recipes"
@page "/recipes/{Category}"
@using RecipeSharing.Models
@using RecipeSharing.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes</PageTitle>

<h1>Browse Recipes</h1>

@if (!string.IsNullOrEmpty(Category))
{
    <p>Filtered by: <span class="badge bg-secondary">@Category</span></p>
    <a href="/recipes" class="btn btn-outline-secondary btn-sm mb-3">Show All</a>
}

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
    @foreach (var recipe in _recipes)
    {
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-info text-dark mb-2">@recipe.Category</span>
                    <p class="card-text">@GetStarDisplay(recipe.AverageRating) (@recipe.AverageRating)</p>
                </div>
                <div class="card-footer">
                    <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@if (!_recipes.Any())
{
    <div class="alert alert-info mt-3">No recipes found in this category.</div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private List<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(Category) && Enum.TryParse<RecipeCategory>(Category, true, out var cat))
        {
            _recipes = RecipeService.GetByCategory(cat);
        }
        else
        {
            _recipes = RecipeService.GetAllRecipes();
        }
    }

    private static string GetStarDisplay(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeSharing.Models
@using RecipeSharing.Services
@using RecipeSharing.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

@if (_recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <h1>@_recipe.Title</h1>
    <span class="badge bg-info text-dark mb-3">@_recipe.Category</span>

    <h4 class="mt-3">Ingredients</h4>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h4>Steps</h4>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <h4>Rating</h4>
    <p>@GetStarDisplay(_recipe.AverageRating) @_recipe.AverageRating / 5 (@_recipe.RatingCount ratings)</p>

    <StarRating RecipeId="_recipe.Id" CurrentRating="_recipe.AverageRating" RatingCount="_recipe.RatingCount" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }

    private static string GetStarDisplay(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@rendermode InteractiveServer
@using RecipeSharing.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @if (_hasRated)
    {
        <p class="text-success fw-bold">Thanks for rating!</p>
    }
    else
    {
        <span class="me-2">Rate this recipe:</span>
        @for (int i = 1; i <= 5; i++)
        {
            var starValue = i;
            <span class="star @(starValue <= (_hoverRating > 0 ? _hoverRating : 0) ? "star-filled" : "")"
                  @onclick="() => SubmitRating(starValue)"
                  @onmouseover="() => _hoverRating = starValue"
                  @onmouseout="() => _hoverRating = 0">
                @(starValue <= (_hoverRating > 0 ? _hoverRating : 0) ? "★" : "☆")
            </span>
        }
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoverRating;
    private bool _hasRated;

    private void SubmitRating(int rating)
    {
        RecipeService.SubmitRating(RecipeId, rating);
        _hasRated = true;
    }
}

.star-rating {
    margin-top: 0.5rem;
}

.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star-filled {
    color: gold;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeSharing.Models;

public class RecipeSubmitModel
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public RecipeCategory? Category { get; set; }

    [Required(ErrorMessage = "At least one ingredient is required.")]
    public string IngredientsText { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one step is required.")]
    public string StepsText { get; set; } = string.Empty;
}

@page "/submit-recipe"
@rendermode InteractiveServer
@using RecipeSharing.Models
@using RecipeSharing.Services
@inject RecipeService RecipeService

<PageTitle>Submit Recipe</PageTitle>

<h1>Submit a New Recipe</h1>

@if (_submittedRecipe is not null)
{
    <div class="alert alert-success">
        <strong>Recipe submitted successfully!</strong>
        <a href="/recipe/@_submittedRecipe.Id">View your recipe: @_submittedRecipe.Title</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in Enum.GetValues<RecipeCategory>())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.IngredientsText" />
            <ValidationMessage For="() => _model.IngredientsText" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.StepsText" />
            <ValidationMessage For="() => _model.StepsText" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmitModel _model = new();
    private Recipe? _submittedRecipe;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category!.Value,
            Ingredients = _model.IngredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = _model.StepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            AverageRating = 0,
            RatingCount = 0
        };

        _submittedRecipe = RecipeService.AddRecipe(recipe);
    }
}

