@page "/recipes"
@page "/recipes/{Category}"
@using RecipeSharing.Models
@using RecipeSharing.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes</PageTitle>

<h1>Browse Recipes</h1>

@if (!string.IsNullOrEmpty(Category))
{
    <p>Filtered by: <span class="badge bg-secondary">@Category</span></p>
    <a href="/recipes" class="btn btn-outline-secondary btn-sm mb-3">Show All</a>
}

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
    @foreach (var recipe in _recipes)
    {
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-info text-dark mb-2">@recipe.Category</span>
                    <p class="card-text">@GetStarDisplay(recipe.AverageRating) (@recipe.AverageRating)</p>
                </div>
                <div class="card-footer">
                    <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@if (!_recipes.Any())
{
    <div class="alert alert-info mt-3">No recipes found in this category.</div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private List<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(Category) && Enum.TryParse<RecipeCategory>(Category, true, out var cat))
        {
            _recipes = RecipeService.GetByCategory(cat);
        }
        else
        {
            _recipes = RecipeService.GetAllRecipes();
        }
    }

    private static string GetStarDisplay(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeSharing.Models
@using RecipeSharing.Services
@using RecipeSharing.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

@if (_recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <h1>@_recipe.Title</h1>
    <span class="badge bg-info text-dark mb-3">@_recipe.Category</span>

    <h4 class="mt-3">Ingredients</h4>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h4>Steps</h4>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <h4>Rating</h4>
    <p>@GetStarDisplay(_recipe.AverageRating) @_recipe.AverageRating / 5 (@_recipe.RatingCount ratings)</p>

    <StarRating RecipeId="_recipe.Id" CurrentRating="_recipe.AverageRating" RatingCount="_recipe.RatingCount" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }

    private static string GetStarDisplay(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@rendermode InteractiveServer
@using RecipeSharing.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @if (_hasRated)
    {
        <p class="text-success fw-bold">Thanks for rating!</p>
    }
    else
    {
        <span class="me-2">Rate this recipe:</span>
        @for (int i = 1; i <= 5; i++)
        {
            var starValue = i;
            <span class="star @(starValue <= (_hoverRating > 0 ? _hoverRating : 0) ? "star-filled" : "")"
                  @onclick="() => SubmitRating(starValue)"
                  @onmouseover="() => _hoverRating = starValue"
                  @onmouseout="() => _hoverRating = 0">
                @(starValue <= (_hoverRating > 0 ? _hoverRating : 0) ? "★" : "☆")
            </span>
        }
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoverRating;
    private bool _hasRated;

    private void SubmitRating(int rating)
    {
        RecipeService.SubmitRating(RecipeId, rating);
        _hasRated = true;
    }
}

.star-rating {
    margin-top: 0.5rem;
}

