    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star-filled {
    color: gold;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeSharing.Models;

public class RecipeSubmitModel
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public RecipeCategory? Category { get; set; }

    [Required(ErrorMessage = "At least one ingredient is required.")]
    public string IngredientsText { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one step is required.")]
    public string StepsText { get; set; } = string.Empty;
}

@page "/submit-recipe"
@rendermode InteractiveServer
@using RecipeSharing.Models
@using RecipeSharing.Services
@inject RecipeService RecipeService

<PageTitle>Submit Recipe</PageTitle>

<h1>Submit a New Recipe</h1>

@if (_submittedRecipe is not null)
{
    <div class="alert alert-success">
        <strong>Recipe submitted successfully!</strong>
        <a href="/recipe/@_submittedRecipe.Id">View your recipe: @_submittedRecipe.Title</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in Enum.GetValues<RecipeCategory>())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.IngredientsText" />
            <ValidationMessage For="() => _model.IngredientsText" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.StepsText" />
            <ValidationMessage For="() => _model.StepsText" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmitModel _model = new();
    private Recipe? _submittedRecipe;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category!.Value,
            Ingredients = _model.IngredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = _model.StepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            AverageRating = 0,
            RatingCount = 0
        };

        _submittedRecipe = RecipeService.AddRecipe(recipe);
    }
}

