 using RecipeSharing.Models;

 namespace RecipeSharing.Services;

 public class RecipeService
 {
     private readonly ConcurrentDictionary<int, Recipe> _recipes = new();
     private int _nextId;

     public RecipeService()
     {
         var seeds = new List<Recipe>
         {
             new()
             {
                 Id = 1, Title = "Classic Pancakes", Category = RecipeCategory.Breakfast,
                 Ingredients = ["2 cups all-purpose flour", "2 tablespoons sugar", "1 tablespoon baking powder", "1/2 teaspoon salt", "2 eggs", "1 1/2 cups milk", "1/4 cup melted butter"],
                 Steps = ["Mix flour, sugar, baking powder, and salt in a bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Heat a griddle over medium heat and grease lightly.", "Pour 1/4 cup batter per pancake and cook until bubbles form, then flip.", "Serve warm with maple syrup and fresh berries."],
                 AverageRating = 4.5, RatingCount = 12
             },
             new()
             {
                 Id = 2, Title = "Chicken Caesar Wrap", Category = RecipeCategory.Lunch,
                 Ingredients = ["2 grilled chicken breasts, sliced", "4 large flour tortillas", "2 cups romaine lettuce, chopped", "1/2 cup Caesar dressing", "1/4 cup grated Parmesan", "1/2 cup croutons, crushed"],
                 Steps = ["Slice grilled chicken into thin strips.", "Warm tortillas in a dry skillet for 30 seconds each.", "Spread Caesar dressing down the center of each tortilla.", "Layer lettuce, chicken, Parmesan, and crushed croutons.", "Fold sides in and roll tightly.", "Slice in half and serve."],
                 AverageRating = 4.2, RatingCount = 8
             },
             new()
             {
                 Id = 3, Title = "Beef Stir-Fry", Category = RecipeCategory.Dinner,
                 Ingredients = ["1 lb flank steak, thinly sliced", "2 tablespoons soy sauce", "1 tablespoon sesame oil", "1 red bell pepper, sliced", "1 cup broccoli florets", "2 cloves garlic, minced", "1 tablespoon cornstarch", "Cooked rice for serving"],
                 Steps = ["Toss steak slices with soy sauce and cornstarch.", "Heat sesame oil in a wok over high heat.", "Sear beef in batches until browned, then set aside.", "Stir-fry bell pepper, broccoli, and garlic for 3 minutes.", "Return beef to the wok and toss everything together.", "Serve immediately over steamed rice."],
                 AverageRating = 4.7, RatingCount = 15
             },
             new()
             {
                 Id = 4, Title = "Chocolate Lava Cake", Category = RecipeCategory.Desserts,
                 Ingredients = ["4 oz dark chocolate", "1/2 cup unsalted butter", "1 cup powdered sugar", "2 eggs", "2 egg yolks", "6 tablespoons flour", "Butter and cocoa for ramekins"],
                 Steps = ["Preheat oven to 425°F. Grease ramekins with butter and dust with cocoa.", "Melt chocolate and butter together in a microwave, stirring every 30 seconds.", "Stir in powdered sugar until smooth.", "Whisk in eggs and egg yolks, then fold in flour.", "Divide batter among ramekins.", "Bake for 12-14 minutes until edges are firm but center is soft. Invert onto plates and serve immediately."],
                 AverageRating = 4.9, RatingCount = 20
             },
             new()
             {
                 Id = 5, Title = "Bruschetta", Category = RecipeCategory.Appetizers,
                 Ingredients = ["1 French baguette, sliced", "4 ripe tomatoes, diced", "1/4 cup fresh basil, chopped", "2 cloves garlic, minced", "2 tablespoons olive oil", "1 tablespoon balsamic vinegar", "Salt and pepper to taste"],
                 Steps = ["Preheat oven to 400°F.", "Arrange baguette slices on a baking sheet and toast for 5 minutes.", "Mix tomatoes, basil, garlic, olive oil, and balsamic vinegar.", "Season with salt and pepper.", "Spoon tomato mixture onto toasted bread.", "Serve immediately as a fresh appetizer."],
                 AverageRating = 4.3, RatingCount = 10
             },
             new()
             {
                 Id = 6, Title = "Mango Smoothie", Category = RecipeCategory.Beverages,
                 Ingredients = ["2 ripe mangoes, peeled and cubed", "1 cup Greek yogurt", "1/2 cup orange juice", "1 tablespoon honey", "1 cup ice cubes", "Fresh mint for garnish"],
                 Steps = ["Add mango, yogurt, orange juice, and honey to a blender.", "Blend on high until smooth.", "Add ice cubes and blend again until frothy.", "Pour into glasses.", "Garnish with a sprig of fresh mint.", "Serve immediately."],
                 AverageRating = 4.6, RatingCount = 9
             }
         };

         foreach (var recipe in seeds)
         {
             _recipes[recipe.Id] = recipe;
         }

         _nextId = seeds.Count;
     }

     public List<Recipe> GetAllRecipes() => [.. _recipes.Values.OrderBy(r => r.Id)];

     public List<Recipe> GetByCategory(RecipeCategory category) =>
         [.. _recipes.Values.Where(r => r.Category == category).OrderBy(r => r.Id)];

     public Recipe? GetById(int id) => _recipes.GetValueOrDefault(id);

     public Recipe AddRecipe(Recipe recipe)
     {
         var id = Interlocked.Increment(ref _nextId);
         recipe.Id = id;
         _recipes[id] = recipe;
         return recipe;
     }

     public void SubmitRating(int recipeId, int rating)
     {
         if (_recipes.TryGetValue(recipeId, out var recipe))
         {
             lock (recipe)
             {
                 var totalRating = recipe.AverageRating * recipe.RatingCount + rating;
                 recipe.RatingCount++;
                 recipe.AverageRating = Math.Round(totalRating / recipe.RatingCount, 1);
             }
         }
     }
 }

